    """
    Dados de versões anteriores:
    - cada pedido já pago vira um Payment (caixa e relatórios usam pagamentos);
    - mesas usadas no histórico viram mesas cadastradas (mapa de mesas);
    - lojas que já têm cardápio pulam o assistente de configuração inicial.
    """
    import re
    import secrets

    Order = apps.get_model('restaurante', 'Order')
    Payment = apps.get_model('restaurante', 'Payment')
    Table = apps.get_model('restaurante', 'Table')
    Product = apps.get_model('restaurante', 'Product')
    AppSettings = apps.get_model('restaurante', 'AppSettings')

    payments = [
        Payment(order_id=order.id, method=order.payment_method or 'dinheiro', amount=order.total,
                created_by_id=order.closed_by_id)
        for order in Order.objects.filter(status='finalizado', total__gt=0)
    ]
    Payment.objects.bulk_create(payments)
    # created_at é auto_now_add: alinhar com a data real de pagamento.
    for payment in Payment.objects.select_related('order'):
        Payment.objects.filter(pk=payment.pk).update(created_at=payment.order.closed_at or payment.order.updated_at)

    names = (
        Order.objects.filter(order_type='dine-in').exclude(mesa__in=['', 'SEM MESA', 'DELIVERY'])
        .values_list('mesa', flat=True).distinct()
    )
    for name in names:
        name = name.strip().upper()[:20]
        if name.isdigit():
            name = str(int(name))  # '01' e '1' são a mesma mesa
        if name and re.fullmatch(r'[0-9A-Z-]{1,6}', name) and not Table.objects.filter(name=name).exists():
            order = int(name) if name.isdigit() else 1000
            Table.objects.create(name=name, order=order, public_token=secrets.token_urlsafe(9))

    OrderItem = apps.get_model('restaurante', 'OrderItem')
    OrderItem.objects.update(printed_quantity=models.F('quantity'))

    if Product.objects.exists():
        AppSettings.objects.update(setup_completed=True)


